import ballerina/io;
import ballerina/time;

public function main() returns error? {
    string doc = "<root>";
    foreach int i in 0 ..< 60 {
        doc += string `<item id="${i}">v${i}</item>`;
    }
    doc += "</root>";
    foreach int b in 0 ..< 5 {
        decimal t0 = time:monotonicNow();
        foreach int _ in 0 ..< 60 {
            _ = check xml:fromString(doc);
        }
        io:println("batch ", b, ": ", time:monotonicNow() - t0, "s");
    }
}
